async function readMusicFile(file,filename){
 const record={title:file.name.replace(/\.[^.]+$/,''),artist:'未标注歌手',album:'未标注专辑',cover:'wind',duration:null,format:file.name.split('.').at(-1).toUpperCase(),filename,imported:true,size:file.size,modified:file.lastModified,metadataRead:false};
 if(record.format!=='FLAC')return record;
 const magic=new Uint8Array(await file.slice(0,4).arrayBuffer());if(String.fromCharCode(...magic)!=='fLaC')return record;
 let offset=4;for(let blocks=0;blocks<128;blocks++){
  const header=new Uint8Array(await file.slice(offset,offset+4).arrayBuffer());if(header.length<4)break;
  const kind=header[0]&127,length=(header[1]<<16)|(header[2]<<8)|header[3];offset+=4;
  if(kind===0&&length===34){const bytes=new Uint8Array(await file.slice(offset,offset+length).arrayBuffer()),view=new DataView(bytes.buffer);if(bytes.length===34){record.sampleRate=(bytes[10]<<12)|(bytes[11]<<4)|(bytes[12]>>4);record.bitDepth=(((bytes[12]&1)<<4)|(bytes[13]>>4))+1;const samples=(bytes[13]&15)*4294967296+view.getUint32(14);record.duration=record.sampleRate?samples/record.sampleRate:null;}}
  if(kind===4&&length<=4*1024*1024){const bytes=new Uint8Array(await file.slice(offset,offset+length).arrayBuffer()),view=new DataView(bytes.buffer);let cursor=0;const number=()=>{if(cursor+4>bytes.length)throw Error('FLAC 标签不完整');const n=view.getUint32(cursor,true);cursor+=4;return n;};try{cursor=4+number();const count=number();for(let i=0;i<count&&i<10000;i++){const size=number();if(cursor+size>bytes.length)break;const item=new TextDecoder().decode(bytes.subarray(cursor,cursor+size));cursor+=size;const split=item.indexOf('='),key=item.slice(0,split).toUpperCase(),value=item.slice(split+1);if(['TITLE','ARTIST','ALBUM'].includes(key)&&value.trim())record[key.toLowerCase()]=value;if(['LYRICS','UNSYNCEDLYRICS'].includes(key))record.embeddedLrc=value;}record.metadataRead=true;}catch{/* Keep filename fallback for malformed tags. */}}
  offset+=length;if(header[0]&128)break;
 }
 return record;
}
function recordFolderChanges(added,removed,updated,source='目录同步'){const stamp=new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}).format(new Date());folderNotice=stamp+' · 新增 '+added+' / 移除 '+removed+' / 更新 '+updated;folderChanges.unshift({stamp,source,added,removed,updated});folderChanges=folderChanges.slice(0,5);}
function removeIndexedSongs(ids){for(let i=songs.length-1;i>=0;i--)if(ids.includes(songs[i].id))songs.splice(i,1);queue=queue.filter(id=>!ids.includes(id));state.libraryCustomOrder=state.libraryCustomOrder.filter(id=>!ids.includes(id));state.libraryRandomOrder=state.libraryRandomOrder.filter(id=>!ids.includes(id));state.playlists.forEach(p=>{p.ids=p.ids.filter(id=>!ids.includes(id));if(p.randomOrder)p.randomOrder=p.randomOrder.filter(id=>!ids.includes(id));});ids.forEach(id=>delete state.lyricsBySong[id]);if(ids.includes(current)){current=songs[0]?.id||1;position=0;playing=false;}}
