async function scanFolder(force=false){
 if(!folderHandle)return;if(folderScanning){if(force)folderRefreshPending=true;return;}folderScanning=true;const handle=folderHandle,source=folderSource;
 try{
  const files=[];async function walk(handle,prefix=''){for await(const [name,entry]of handle.entries()){const path=prefix+name;if(entry.kind==='directory')await walk(entry,path+'/');else if(/\.(flac|mp3|wav|m4a|aac|ogg|opus|lrc)$/i.test(name))files.push({path,file:await entry.getFile()});}}await walk(handle);if(handle!==folderHandle)return;
  const allMusic=files.filter(x=>!x.path.toLowerCase().endsWith('.lrc')),incoming=[],full=force||performance.now()-lastFullScan>30000;const lyricFiles=new Map();for(const entry of files.filter(x=>x.path.toLowerCase().endsWith('.lrc')))if(entry.file.size<=512*1024)lyricFiles.set(entry.path.replace(/\.lrc$/i,''),await entry.file.text());
  for(const entry of allMusic){const old=songs.find(s=>s.source===source&&s.filename===entry.path);let record=old;if(full||!old||old.size!==entry.file.size||old.modified!==entry.file.lastModified)record={...await readMusicFile(entry.file,entry.path),id:old?.id,source:source};const lrc=lyricFiles.get(entry.path.replace(/\.[^.]+$/,''))||record.embeddedLrc||'';incoming.push({...record,lrc});}
  const removed=songs.filter(s=>s.source===source&&!incoming.some(n=>n.filename===s.filename)).map(s=>s.id);let added=0,updated=0,nextId=Math.max(0,...songs.map(s=>s.id))+1;
  for(const record of incoming){const old=songs.find(s=>s.source===source&&s.filename===record.filename);if(!old){record.id=nextId++;songs.push(record);added++;}else if(['title','artist','album','size','modified','duration','sampleRate','bitDepth','lrc'].some(k=>old[k]!==record[k])){Object.assign(old,record);updated++;}if(!state.lyricsBySong[record.id]?.manual){if(record.lrc&&parseLrc(record.lrc).length)state.lyricsBySong[record.id]={name:record.filename.replace(/\.[^.]+$/,'.lrc'),text:record.lrc};else delete state.lyricsBySong[record.id];}}
  removeIndexedSongs(removed);if(full)lastFullScan=performance.now();if(force||added||removed.length||updated){recordFolderChanges(added,removed.length,updated);persist();if(['library','albums','artists','playlist','folders','info'].includes(screen)&&!$('#overlay-root').innerHTML)render();else if(screen==='lyrics'){const area=$('.lyrics-area');if(area){$('.lyrics-lines').innerHTML=lyricLines();layoutLyrics();updateLyrics(true);}}}
 }catch(error){folderNotice='目录读取失败，请重新授权；音乐索引未删除';if(screen==='folders')render();if(force)toast(folderNotice);}
 finally{folderScanning=false;if(folderRefreshPending){folderRefreshPending=false;scanFolder(true);}}
}
async function connectFolder(){if(!window.showDirectoryPicker){toast('当前浏览器不能持续访问目录；本次仅导入文件列表');$('#music-folder').click();return;}try{const selected=await window.showDirectoryPicker({mode:'read'});if(!folderHandle||!await selected.isSameEntry(folderHandle)){folderSource='folder-'+Date.now();folderHandle=selected;}lastFullScan=0;await scanFolder(true);if(screen==='folders')render();}catch(error){if(error.name!=='AbortError')toast('未获得目录访问权限，请重新选择');}}
function demonstrateFolderChange(){let added=0,removed=0,updated=0;demoChange=(demoChange%3)+1;if(demoChange===1){if(!songs.some(s=>s.demoAdded)){songs.push({id:Math.max(...songs.map(s=>s.id))+1,title:'清晨散步',artist:'南屿',album:'海边散步',cover:'sea',duration:219,format:'FLAC',demoAdded:true});added=1;}}else if(demoChange===2){const s=songs.find(s=>s.id===1);if(s){s.title=s.title==='晚风来信'?'晚风来信 · 重制版':'晚风来信';s.album=s.album==='晚风来信'?'晚风来信 · 新标签':'晚风来信';updated=1;}}else{const ids=songs.filter(s=>s.demoAdded).map(s=>s.id);removeIndexedSongs(ids);removed=ids.length;}recordFolderChanges(added,removed,updated,'示例变更');render();toast('已同步示例变更；真实文件未被修改');}
