function orderedIds(ids,target=null){
 const config=target===null?{sort:state.librarySort,custom:state.libraryCustomOrder,random:state.libraryRandomOrder}:state.playlists.find(p=>p.id===target);
 const order=config?.sort||'custom', base=[...new Set(ids)].filter(id=>songs.some(s=>s.id===id));
 if(order==='title'||order==='artist')return base.sort((a,b)=>songCollator.compare(getSong(a)[order],getSong(b)[order])||songCollator.compare(getSong(a).title,getSong(b).title)||a-b);
 const stored=order==='random'?(target===null?config.random:config.randomOrder):(target===null?config.custom:ids);
 return [...(Array.isArray(stored)?stored:[]).filter(id=>base.includes(id)),...base.filter(id=>!stored?.includes(id))];
}
function randomized(ids){const list=[...ids];for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]];}return list;}
function sortButton(target=null){const key=target===null?state.librarySort:state.playlists.find(p=>p.id===target)?.sort||'custom';return '<button class="text-btn muted" data-action="sort" data-target="'+(target??'library')+'">'+icon('list')+sortNames[key]+'</button>';}
function sortMenu(target=null){sortTarget=target;const key=target===null?state.librarySort:state.playlists.find(p=>p.id===target)?.sort||'custom';overlay('歌曲排序','<p class="footnote sort-note">中文名称按拼音顺序排列</p>'+Object.entries(sortNames).map(([k,label])=>'<button class="choice-row '+(k===key?'selected':'')+'" data-action="sort-choice" data-name="'+k+'"><span class="choice-text"><strong>'+label+'</strong></span><span class="radio"></span></button>').join(''));}
function customSort(target=sortTarget){sortTarget=target;const ids=target===null?songs.map(s=>s.id):state.playlists.find(p=>p.id===target).ids;sortDraft=orderedIds(ids,target);overlay('自定义顺序','<p class="footnote sort-note">拖动右侧手柄调整，完成后保存</p><div class="order-list">'+sortDraft.map((id,i)=>'<div class="order-row" data-sort-id="'+id+'"><span class="song-index" data-number>'+ (i+1)+'</span><span class="song-copy"><strong>'+esc(getSong(id).title)+'</strong><small>'+esc(getSong(id).artist)+'</small></span><button class="icon-btn" data-action="order-up" data-id="'+id+'" aria-label="上移'+esc(getSong(id).title)+'">'+icon('up')+'</button><button class="icon-btn" data-action="order-down" data-id="'+id+'" aria-label="下移'+esc(getSong(id).title)+'">'+icon('down')+'</button><button class="icon-btn order-handle" aria-label="拖动'+esc(getSong(id).title)+'排序" data-reorder="'+id+'">'+icon('grip')+'</button></div>').join('')+'</div>',false,'<div class="order-footer"><button class="secondary" data-action="close">取消</button><button class="primary" data-action="save-order">保存顺序</button></div>');refreshDraft();}
function refreshDraft(){const list=$('.order-list');if(!list||!sortDraft)return;sortDraft.forEach((id,i)=>{const row=list.querySelector('[data-sort-id="'+id+'"]');list.append(row);row.querySelector('[data-number]').textContent=i+1;row.querySelector('[data-action="order-up"]').disabled=i===0;row.querySelector('[data-action="order-down"]').disabled=i===sortDraft.length-1;});}
function moveDraft(id,index){if(!sortDraft)return;const from=sortDraft.indexOf(id);if(from<0||index<0||index>=sortDraft.length||from===index)return;sortDraft.splice(from,1);sortDraft.splice(index,0,id);refreshDraft();}
function parseLrc(text){
 const entries=[];for(const line of text.replace(/^\uFEFF/,'').split(/\r?\n/)){const tags=[...line.matchAll(/\[(\d{1,3}):([0-5]?\d)(?:[.:](\d{1,3}))?\]/g)];if(!tags.length)continue;const words=line.replace(/\[[^\]]*\]/g,'').trim();for(const tag of tags)entries.push({at:Number(tag[1])*60+Number(tag[2])+(tag[3]?Number('0.'+tag[3]):0),text:words});}return entries.sort((a,b)=>a.at-b.at);
}
function trackLyrics(){const custom=state.lyricsBySong[current],raw=custom?.text||(getSong(current).imported?'':demoLrc);if(!lrcCache.has(raw))lrcCache.set(raw,parseLrc(raw));return lrcCache.get(raw);}
function lyricIndex(entries,seconds){let low=0,high=entries.length;while(low<high){const middle=(low+high)>>1;if(entries[middle].at<=seconds)low=middle+1;else high=middle;}return low-1;}
function stopLyricAnimation(){cancelAnimationFrame(lyricAnimation);lyricAnimation=0;}
function layoutLyrics(){const area=$('.lyrics-area'),row=$('.lyric-line');if(area&&row)area.style.paddingBlock=Math.max(0,(area.clientHeight-row.clientHeight)/2)+'px';}
function scrollLyrics(force=false){
 if(lyricBrowsing&&!force)return;const area=$('.lyrics-area'),line=$('.lyric-line.current');if(!area||!line)return;
 stopLyricAnimation();const bounds=area.getBoundingClientRect(),box=line.getBoundingClientRect(),start=area.scrollTop,target=Math.max(0,Math.min(area.scrollHeight-area.clientHeight,start+box.top-bounds.top+box.height/2-bounds.height/2));
 if(!state.dynamic||matchMedia('(prefers-reduced-motion: reduce)').matches){area.scrollTop=target;return;}
 const begin=performance.now();function frame(now){if(!area.isConnected||lyricBrowsing)return;const fraction=Math.min(1,(now-begin)/420);area.scrollTop=start+(target-start)*(1-Math.pow(1-fraction,3));if(fraction<1)lyricAnimation=requestAnimationFrame(frame);else lyricAnimation=0;}lyricAnimation=requestAnimationFrame(frame);
}
function updateLyrics(force=false){
 const entries=trackLyrics(),index=lyricIndex(entries,position),stamp=entries[index]?.at,key=current+':'+index;
 if(force||key!==lyricKey){lyricKey=key;document.querySelectorAll('.lyric-line').forEach((row,i)=>{const active=stamp!==undefined&&entries[i]?.at===stamp;row.classList.toggle('current',active);if(active)row.setAttribute('aria-current','true');else row.removeAttribute('aria-current');});scrollLyrics(force);}
 const preview=$('.player-lyric-preview');if(preview){preview.querySelector('span').textContent=entries[index]?.text|| (entries.length?'等待歌词开始':'暂无歌词');preview.querySelector('small').textContent=entries[index+1]?.text||'点击查看完整歌词';}
}
function browseLyrics(){lyricBrowsing=true;stopLyricAnimation();clearTimeout(lyricResumeTimer);const status=$('.lyric-follow-status');if(status){status.querySelector('span').textContent='浏览中 · 停止操作 4 秒后归位';status.querySelector('button').hidden=false;}lyricResumeTimer=setTimeout(resumeLyrics,4000);}
function resumeLyrics(){lyricBrowsing=false;clearTimeout(lyricResumeTimer);const status=$('.lyric-follow-status');if(status){status.querySelector('span').textContent='LRC · 随播放定位';status.querySelector('button').hidden=true;}updateLyrics(true);}
function updateProgress(){const duration=getSong(current).duration||248,seek=$('#seek');if(seek){seek.value=position;seek.style.setProperty('--progress',position/duration*100+'%');$('#elapsed').textContent=time(position);}const progress=$('.mini-progress');if(progress)progress.style.width=position/duration*100+'%';}
function applyTheme(){const t=themes.find(t=>t.name===state.theme)||themes[0]; document.documentElement.style.setProperty('--accent',t.color);document.documentElement.style.setProperty('--soft',t.soft);document.documentElement.style.setProperty('--lyric-size',state.size+'px');document.documentElement.style.setProperty('--lyric-gap',state.lineGap+'px');document.documentElement.style.setProperty('--lyric-font',state.font==='宋体'?'SimSun, serif':state.font==='楷体'?'KaiTi, serif':'"Segoe UI", "Microsoft YaHei", sans-serif');}
function backgroundImage(){return state.background.source==='cover'?art(getSong(current).cover):state.background.source==='local'?backgroundUrl:'';}
function backgroundLayer(){const src=backgroundImage();return src?'<img src="'+esc(src)+'" alt="">':'';}
function applyBackground(){const b=state.background,style=document.documentElement.style;style.setProperty('--background-opacity',b.opacity/100);style.setProperty('--background-scale',b.scale/100);style.setProperty('--background-x',b.x+'%');style.setProperty('--background-y',b.y+'%');const active=['player','lyrics','queue'].includes(screen);$('#device').classList.toggle('player-context',active);$('#device').classList.toggle('has-background',active&&Boolean(backgroundImage()));$('#player-background').innerHTML=active?backgroundLayer():'';}
function backgroundStore(action,file){return new Promise((resolve,reject)=>{const open=indexedDB.open('xiaohonghua-images',1);open.onupgradeneeded=()=>open.result.createObjectStore('images');open.onerror=()=>reject(open.error);open.onblocked=()=>reject(Error('图片存储被占用'));open.onsuccess=()=>{const db=open.result,tx=db.transaction('images',action==='get'?'readonly':'readwrite'),store=tx.objectStore('images');const request=action==='get'?store.get('player'):store.put(file,'player');tx.oncomplete=()=>{db.close();resolve(request.result);};tx.onabort=()=>{db.close();reject(tx.error);};};});}
function backgroundSlider(key,label,min,max,suffix='%'){const value=state.background[key];return '<label class="background-control" for="background-'+key+'"><span>'+label+'<output id="background-'+key+'-value">'+value+suffix+'</output></span><input type="range" id="background-'+key+'" data-background="'+key+'" min="'+min+'" max="'+max+'" value="'+value+'" aria-label="'+label+'"></label>';}
function backgroundPage(){const b=state.background,s=getSong(current);return compact('播放背景','',btn('check','background-done','完成背景设置'))+'<div class="scroll-area background-editor"><div class="background-preview '+(backgroundImage()?'with-image':'')+'"><div class="background-preview-art">'+backgroundLayer()+'</div><span class="background-preview-heading">正在播放</span><img class="background-preview-cover" src="'+art(s.cover)+'" alt=""><strong>'+esc(s.title)+'</strong><p>我把今天慢慢听完</p><div class="background-preview-controls"><span></span>'+icon('prev')+icon('play')+icon('next')+'</div></div><div class="background-options" role="group" aria-label="背景来源"><button class="'+(b.source==='none'?'selected':'')+'" data-action="background-source" data-name="none">纯色</button><button class="'+(b.source==='cover'?'selected':'')+'" data-action="background-source" data-name="cover">歌曲封面</button><button class="'+(b.source==='local'?'selected':'')+'" data-action="background-source" data-name="local">本地图片</button></div><button class="background-import secondary" data-action="background-import">'+icon('upload')+(backgroundUrl?'从相册更换图片':'从本地相册选择')+'</button><p class="background-filename">'+esc(b.source==='local'?(backgroundName||'还未选择图片'):'保持图片比例，自动裁切铺满')+'</p>'+backgroundSlider('opacity','背景不透明度',0,100)+backgroundSlider('scale','图片大小',100,250)+backgroundSlider('x','水平位置',0,100)+backgroundSlider('y','垂直位置',0,100)+'<div class="background-position-labels"><span>左 / 上</span><span>右 / 下</span></div><button class="text-btn accent" data-action="background-reset">恢复默认背景</button><p class="footnote">支持 JPG、PNG、WebP，最大 20 MB。缩放和移动只影响显示，原图保持不变。图片保存在当前浏览器；安卓版本使用系统相册。</p></div>';}
function header(title, subtitle='', actions=''){return '<header class="page-header"><div><h1>'+esc(title)+'</h1>'+(subtitle?'<p>'+esc(subtitle)+'</p>':'')+'</div><div class="header-actions">'+actions+'</div></header>';}
function compact(title,sub='',action=''){return '<header class="compact-header">'+btn('back','back','返回')+'<div class="header-middle"><strong>'+esc(title)+'</strong>'+(sub?'<small>'+esc(sub)+'</small>':'')+'</div>'+(action||'<span class="icon-btn" aria-hidden="true"></span>')+'</header>';}
function nav(active){return '<nav class="bottom-nav" aria-label="主导航">'+[['library','music','音乐库'],['playlists','list','歌单'],['settings','settings','设置']].map(([r,i,l])=>'<button data-page="'+r+'" class="'+(active===r?'active':'')+'"><span class="nav-pill">'+icon(i)+'</span><span>'+l+'</span></button>').join('')+'</nav>';}
function mini(){const s=getSong(current);return '<div class="mini-player"><button class="mini-open" data-page="player" aria-label="打开正在播放"><img src="'+art(s.cover)+'" alt=""><span><strong>'+esc(s.title)+'</strong><small>'+esc(s.artist)+'</small></span></button>'+btn(playing?'pause':'play','play',playing?'暂停':'播放')+btn('list','queue','播放队列')+'<div class="mini-progress" style="width:'+(position/(s.duration||248)*100)+'%"></div></div>';}
function row(s,index,options={}){return '<div class="song-row '+(options.number?'numbered ':'')+(current===s.id?'is-current':'')+'">'+(options.number?'<span class="song-index">'+(index+1)+'</span>':'')+'<button class="song-hit" data-action="song" data-id="'+s.id+'">'+(!options.hideCover?'<img class="cover cover-small" src="'+art(s.cover)+'" alt="">':'')+'<span class="song-copy"><strong class="song-title">'+esc(s.title)+'</strong><span class="song-sub">'+esc(s.artist)+' · '+esc(s.album)+'</span></span></button><span class="format">'+s.format+'</span><button class="icon-btn" data-action="song-menu" data-id="'+s.id+'" aria-label="'+esc(s.title)+'的更多操作">'+icon('more')+'</button></div>';}
function tabs(active){return '<div class="tabs" role="navigation" aria-label="音乐分类">'+[['library','歌曲'],['albums','专辑'],['artists','歌手']].map(([r,l])=>'<button class="'+(active===r?'active':'')+'" data-page="'+r+'">'+l+'</button>').join('')+'</div>';}
function library(){let content;if(screen==='albums')content='<div class="cover-grid">'+songs.filter((s,i)=>songs.findIndex(x=>x.album===s.album)===i).map(s=>'<button class="cover-card" data-action="album" data-name="'+esc(s.album)+'"><img src="'+art(s.cover)+'" alt="封面"><strong>'+esc(s.album)+'</strong><small>'+esc(s.artist)+' · '+songs.filter(x=>x.album===s.album).length+' 首</small></button>').join('')+'</div>';else if(screen==='artists')content=songs.filter((s,i)=>songs.findIndex(x=>x.artist===s.artist)===i).map(s=>'<button class="artist-row" data-action="artist" data-name="'+esc(s.artist)+'"><img src="'+art(s.cover)+'" alt=""><span><strong>'+esc(s.artist)+'</strong><small>'+songs.filter(x=>x.artist===s.artist).length+' 首歌曲</small></span>'+icon('chevron')+'</button>').join('');else content='<div class="toolbar"><button class="text-btn" data-action="play-all">'+icon('play')+'播放全部</button>'+sortButton()+'</div>'+orderedIds(songs.map(s=>s.id)).map((id,i)=>row(getSong(id),i,{number:true})).join('');return header('音乐库','共 '+songs.length+' 首本地歌曲',btn('search','search','搜索音乐')+btn('plus','import','导入音乐'))+'<div class="scroll-area">'+tabs(screen)+content+'</div><div class="list-bottom-summary">共 '+songs.length+' 首歌曲</div>'+mini()+nav('library');}
function mosaic(p){return '<span class="playlist-mosaic '+(p.ids.length<4?'single':'')+'">'+(p.ids.length ? (p.ids.length<4?[p.ids[0]]:p.ids.slice(0,4)).map(id=>'<img src="'+art(getSong(id).cover)+'" alt="">').join('') : '<img src="assets/flower.svg" alt="">')+'</span>';}
function playlists(){return header('我的歌单',state.playlists.length+' 个歌单 · 收好每一种心情',btn('plus','create-playlist','新建歌单'))+'<div class="scroll-area"><div class="cover-grid">'+state.playlists.map(p=>'<button class="cover-card" data-action="playlist" data-id="'+p.id+'">'+mosaic(p)+'<strong>'+esc(p.name)+'</strong><small>'+p.ids.length+' 首歌曲</small></button>').join('')+'</div></div>'+mini()+nav('playlists');}
function detail(){let title,sub,ids,cover;if(screen==='playlist'){const p=state.playlists.find(p=>p.id===detailId)||state.playlists[0];if(!p)return playlists();detailId=p.id;title=p.name;ids=orderedIds(p.ids,p.id);sub=ids.length+' 首歌曲 · 我的歌单';cover=mosaic(p);}else{const set=songs.filter(s=>screen==='album'?s.album===album:s.artist===artist);if(!set.length)return library();title=screen==='album'?album:artist;ids=set.map(s=>s.id);sub=screen==='album'?set[0].artist+' · '+ids.length+' 首歌曲':ids.length+' 首歌曲 · 本地音乐';cover='<img src="'+art(set[0].cover)+'" alt="">';}return compact(screen==='playlist'?'歌单':screen==='album'?'专辑':'歌手','',screen==='playlist'?btn('more','playlist-menu','歌单操作'):btn('search','search','搜索音乐'))+'<div class="scroll-area"><div class="detail-hero '+(screen==='artist'?'artist':'')+'">'+cover+'<h2>'+esc(title)+'</h2><p>'+esc(sub)+'</p></div><div class="detail-controls"><button class="primary" data-action="play-detail">'+icon('play')+'播放全部</button>'+(screen==='playlist'?'<button class="secondary" data-action="add-songs">'+icon('plus')+'添加歌曲</button>':'')+'</div>'+(screen==='playlist'?'<div class="toolbar"><small>共 '+ids.length+' 首歌曲</small>'+sortButton(detailId)+'</div>':'')+ids.map((id,i)=>row(getSong(id),i,{number:true,hideCover:true})).join('')+(ids.length?'':'<div class="empty-state"><p>歌单还空着，添加几首喜欢的歌吧。</p></div>')+'</div><div class="list-bottom-summary">共 '+ids.length+' 首歌曲</div>'+mini();}
function controls(){const s=getSong(current);return '<div class="player-controls"><div class="seek-wrap"><input class="seek" id="seek" type="range" min="0" max="'+(s.duration||248)+'" value="'+position+'" style="--progress:'+(position/(s.duration||248)*100)+'%" aria-label="播放进度"><div class="times"><span id="elapsed">'+time(position)+'</span><span>'+time(s.duration)+'</span></div></div><div class="transport">'+btn(mode===3?'shuffle':'repeat','mode',modes[mode],'side')+btn('prev','prev','上一首','skip')+btn(playing?'pause':'play','play',playing?'暂停':'播放','big-play')+btn('next','next','下一首','skip')+btn('list','queue','播放队列','side')+'</div><div class="mode-label">'+modes[mode]+'</div><div class="player-footer"><button class="text-btn" data-action="favorite" aria-label="添加到歌单">'+icon('heart')+'歌单</button><button class="text-btn player-view-toggle" data-page="'+(screen==='lyrics'?'player':'lyrics')+'">'+(screen==='lyrics'?'封面':'歌词')+'</button><button class="text-btn" data-action="player-style">'+icon('palette')+'样式</button></div></div>';}
function lyricLines(){const entries=trackLyrics(),active=entries[lyricIndex(entries,position)]?.at;return entries.map((l,i)=>'<button class="lyric-line '+(l.at===active?'current':'')+'" data-action="lyric-line" data-index="'+i+'"><span>'+esc(l.text||'♪')+'</span></button>').join('');}
function player(){const s=getSong(current),entries=trackLyrics(),line=lyricIndex(entries,position);return compact(screen==='lyrics'?s.title:'正在播放',screen==='lyrics'?s.artist:'本地音乐',btn('more','song-menu','歌曲操作'))+'<div class="player-area '+(screen==='lyrics'?'lyrics-view':'cover-view')+'">'+(screen==='lyrics'?'<div class="lyrics-area" tabindex="0" aria-label="上下滑动浏览歌词"><div class="lyrics-lines '+(state.dynamic?'dynamic':'')+'">'+(entries.length?lyricLines():'<div class="no-lyrics"><p>暂无歌词</p><button class="secondary" data-action="choose-lyric">选择 LRC 歌词</button></div>')+'</div></div><div class="lyric-follow-status"><span>LRC · 随播放定位</span><button data-action="resume-lyrics" hidden>返回当前歌词</button></div>':'<div class="player-main"><img class="player-cover" src="'+art(s.cover)+'" alt="'+esc(s.album)+'封面"><div class="player-title"><h2>'+esc(s.title)+'</h2><p>'+esc(s.artist)+' · '+esc(s.album)+'</p><small class="player-quality">'+s.format+' · '+(s.imported?'待解析':'示例音质 44.1 kHz / 16 bit')+'</small></div><button class="player-lyric-preview" data-page="lyrics" aria-label="打开完整歌词"><span>'+esc(entries[line]?.text||'暂无歌词')+'</span><small>'+esc(entries[line+1]?.text||'左滑查看歌词')+'</small></button></div>')+controls()+'</div>';}
function settingRow(i,title,sub,action,value=''){return '<button class="setting-row" data-action="'+action+'"><span class="setting-icon">'+icon(i)+'</span><span class="setting-copy"><strong>'+title+'</strong>'+(sub?'<small>'+sub+'</small>':'')+'</span>'+(value?'<span class="setting-value">'+value+'</span>':'')+'<span class="chevron">'+icon('chevron')+'</span></button>';}
function toggle(key,label){return '<label class="flower-switch"><input type="checkbox" data-setting="'+key+'" aria-label="'+label+'" '+(state[key]?'checked':'')+'><span class="slider"></span></label>';}
function settings(){return header('设置','让每一次聆听，都合心意')+'<div class="scroll-area"><section class="settings-group"><h2 class="group-label">外观与歌词</h2><div class="settings-card">'+settingRow('palette','主题颜色','给小红花换一种心情','theme',state.theme)+settingRow('font','歌词字体与字号','字体、字号与动态歌词','lyric-settings')+settingRow('palette','播放背景','相册图片、不透明度与位置','background')+'</div></section><section class="settings-group"><h2 class="group-label">播放</h2><div class="settings-card"><div class="setting-row"><span class="setting-icon">'+icon('lock')+'</span><span class="setting-copy"><strong>系统锁屏音乐控件</strong><small>期望设置 · 待实机验证</small></span>'+toggle('lock','系统锁屏音乐控件')+'</div>'+settingRow('clock','定时关闭','睡前听一会儿','timer','未开启')+'</div><p class="footnote">控制安卓系统锁屏上的音乐控件。是否能单独关闭，需要在 Android 16 / HyperOS 上验证。</p></section><section class="settings-group"><h2 class="group-label">本地音乐</h2><div class="settings-card">'+settingRow('upload','导入音乐','文件或整个文件夹','import')+settingRow('folder','音乐文件夹','查看目录与重新扫描','folders')+settingRow('download','备份与恢复','歌单、设置与播放记录','backup')+'</div></section><div class="settings-card">'+settingRow('info','关于小红花','为喜欢的音乐留一个位置','about','v0.1 设计')+'</div></div>'+mini()+nav('settings');}
function lyricSettings(){return compact('歌词样式')+'<div class="scroll-area"><div class="lyric-preview"><span class="preview-label">实时预览</span><p>风把晚霞叠成一封信</p><p class="current">我把今天慢慢听完</p><p>把心事交给远山</p></div><h2 class="setting-section-title">歌词字体</h2><div class="settings-card font-options">'+['系统字体','宋体','楷体'].map(f=>'<button class="choice-row '+(state.font===f?'selected':'')+'" data-action="font" data-name="'+f+'"><span class="choice-text" style="font-family:'+(f==='宋体'?'SimSun,serif':f==='楷体'?'KaiTi,serif':'inherit')+'"><strong>'+f+'</strong><small>'+(f==='系统字体'?'清晰自然，跟随手机系统':f==='宋体'?'像读一首诗':'温柔的手写感')+'</small></span><span class="radio"></span></button>').join('')+'</div><h2 class="setting-section-title">字体大小 <span id="font-size-label">'+state.size+' px</span></h2><div class="size-scale"><span>小</span><input type="range" min="18" max="34" value="'+state.size+'" id="font-size" aria-label="歌词字体大小"><span>大</span></div><h2 class="setting-section-title">行间距 <span id="line-gap-label">'+state.lineGap+' px</span></h2><div class="size-scale"><span>紧</span><input type="range" min="0" max="48" value="'+state.lineGap+'" id="line-gap" aria-label="歌词行间距"><span>宽</span></div><div class="settings-card"><div class="setting-row"><span class="setting-copy"><strong>动态歌词</strong><small>按 LRC 时间戳高亮和平滑定位</small></span>'+toggle('dynamic','动态歌词')+'</div></div><p class="footnote">手动浏览时暂停跟随，停止操作 4 秒后回到当前行。字体效果以手机实际字体为准。</p></div>';}
function themePage(){return compact('主题颜色')+'<div class="scroll-area"><div class="color-preview"><img src="assets/flower.svg" alt="小红花"><h2>听见自己的颜色</h2><p>简单一点，喜欢多一点。</p><button class="primary" data-action="theme-preview">'+icon('play')+'播放喜欢</button></div><h2 class="setting-section-title">选择一种颜色</h2><div class="theme-colors">'+themes.map(t=>'<button class="color-choice '+(state.theme===t.name?'selected':'')+'" data-action="theme-color" data-name="'+t.name+'" style="color:'+t.color+'"><span class="swatch" style="background:'+t.color+'">'+(state.theme===t.name?icon('check'):'')+'</span><span>'+t.name+'</span></button>').join('')+'</div><p class="theme-description">主题色应用于按钮、选中状态和歌词高亮。背景与文字保持清晰、安静。</p><div class="settings-card">'+settingRow('font','再选一款歌词字体','把界面调整到喜欢的样子','lyric-settings')+'</div></div>';}
function importPage(empty=false){return compact(empty?'欢迎来到小红花':'导入音乐')+'<div class="scroll-area"><div class="import-illustration"><div class="folder-art">'+icon('folder')+'<img src="assets/flower.svg" alt=""></div></div><div class="intro-center"><h2>'+ (empty?'让喜欢的音乐，住进手机':'把音乐带到身边')+'</h2><p>选择手机里的音乐文件或文件夹<br>离线聆听，从这里开始</p></div><button class="import-choice" data-action="import-files"><span>'+icon('music')+'</span><div><strong>选择音乐文件</strong><small>一次添加一首或多首歌曲</small></div>'+icon('chevron')+'</button><button class="import-choice" data-action="import-folder"><span>'+icon('folder')+'</span><div><strong>选择音乐文件夹</strong><small>一并查找子文件夹中的音乐</small></div>'+icon('chevron')+'</button><div class="import-info"><p>FLAC · MP3 · WAV · M4A · AAC · OGG · Opus</p><small>正式版本读取原文件，无需再复制一份。原型可读取 FLAC 基本标签，音频播放待实现。</small></div>'+(empty?'<button class="text-btn accent" data-page="library">先看看示例音乐 '+icon('chevron')+'</button>':'')+'</div>';}
function searchPage(){const result=songs.filter(s=>(s.title+s.artist+s.album).toLowerCase().includes(search.toLowerCase()));return compact('搜索音乐')+'<div class="scroll-area"><label class="search-box">'+icon('search')+'<input id="search-input" aria-label="搜索歌曲、歌手或专辑" placeholder="歌曲、歌手或专辑" value="'+esc(search)+'">'+btn('close','clear-search','清空搜索')+'</label><div id="search-results">'+searchResults(result)+'</div></div>'+mini();}
function searchResults(result){return search?'<div class="toolbar"><span class="muted">'+result.length+' 首匹配歌曲</span></div>'+(result.length?result.map((s,i)=>row(s,i)).join(''):'<div class="empty-state">'+icon('search')+'<h2>还没有找到</h2><p>试试歌曲名、歌手或专辑名称。</p></div>'):'<h2 class="setting-section-title">试着找一找</h2><div class="chip-list">'+['晚风','松木','夜航'].map(t=>'<button class="chip" data-action="search-chip" data-name="'+t+'">'+t+'</button>').join('')+'</div><h2 class="setting-section-title">所有歌曲</h2>'+result.map((s,i)=>row(s,i)).join('');}
function infoPage(){const s=getSong(current),fields=[['标题',s.title],['歌手',s.artist],['专辑',s.album],['格式',s.format],['时长',time(s.duration)],['音质',s.sampleRate?(s.sampleRate/1000)+' kHz · '+s.bitDepth+' bit':s.imported?'待解析':'44.1 kHz · 16 bit（示例）'],['歌词',state.lyricsBySong[current]?.name||(s.imported?'未载入':'LRC 时间戳（示例）')],['文件位置',s.imported?s.filename:'Music/'+s.artist+'/'+s.album+'/'+s.title+'.'+s.format.toLowerCase()]];if(s.size!==undefined)fields.push(['文件大小',(s.size/1024/1024).toFixed(2)+' MB'],['修改时间',new Date(s.modified).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})]);return compact('歌曲信息')+'<div class="scroll-area"><img class="info-cover" src="'+art(s.cover)+'" alt="封面"><dl class="info-list">'+fields.map(([a,b])=>'<div><dt>'+a+'</dt><dd>'+esc(b)+'</dd></div>').join('')+'</dl><p class="footnote">示例曲目为演示内容；已授权目录中的 FLAC 可读取基本标签与文件信息。</p><button class="secondary" data-action="choose-lyric">选择歌词文件</button></div>';}
function folders(){return compact('音乐文件夹','文件与标签保持同步',btn('repeat','rescan','刷新音乐文件夹'))+'<div class="scroll-area"><div class="settings-card"><div class="folder-row">'+icon('folder')+'<div><strong>'+esc(folderHandle?.name||'Music · 示例目录')+'</strong><small>'+ (folderHandle?songs.filter(s=>s.source===folderSource).length+' 首歌曲 · 当前已授权目录':'9 首示例歌曲 · 选择真实目录后开始监测')+'</small></div><span class="status-tag">'+(folderHandle?'已连接':'示例')+'</span></div></div><div class="detail-controls"><button class="primary" data-action="rescan">'+icon('repeat')+'刷新</button><button class="secondary" data-action="connect-folder">'+icon('folder')+'选择监测目录</button></div><div class="settings-card"><div class="setting-row"><span class="setting-copy"><strong>自动监测目录变化</strong><small>'+ (folderHandle?(state.monitor?'网页前台每 2 秒检查增删改':'监测已暂停，仍可手动刷新'):'等待选择真实目录')+'</small></span>'+toggle('monitor','自动监测目录变化')+'</div></div><p class="folder-sync-status" role="status">'+esc(folderNotice)+'</p><h2 class="setting-section-title">同步记录</h2><div class="sync-log">'+(folderChanges.length?folderChanges.map(c=>'<div><span>'+c.stamp+' · '+c.source+'</span><p>新增 '+c.added+' · 移除 '+c.removed+' · 更新 '+c.updated+'</p></div>').join(''):'<p class="footnote">暂无变化，刷新会重新读取文件与标签。</p>')+'</div><div class="note-panel"><strong>文件变化，音乐库也跟着更新</strong><p>同步新增、移除和修改。刷新重读 FLAC 标题、歌手、专辑及文件信息；自动检查另有每 30 秒一次的标签重读。</p><button class="text-btn accent" data-action="demo-folder-change">演示增删与标签更新</button></div><p class="footnote">原型只监测当前授权目录，刷新网页后需重新选择；标签解析当前覆盖 FLAC 基本信息。安卓后台监控和其他格式完整标签待实现。</p></div>';}
function backup(){return compact('备份与恢复')+'<div class="scroll-area"><div class="backup-hero">'+icon('download')+'<h2>把喜欢的顺序，也留下</h2><p>歌单和设置，换手机也能带走。</p></div><div class="settings-card">'+settingRow('download','导出原型数据','保存歌单与界面设置为 JSON','export')+settingRow('upload','恢复原型数据','从小红花 UI 备份中恢复','restore')+'</div><div class="note-panel"><strong>音乐文件需要单独迁移</strong><p>备份不包含音乐音频。正式安卓版本恢复后，还需要选择新手机上的音乐目录并重新匹配文件。</p></div><p class="footnote">当前导出仅覆盖 UI 示例的歌单与设置，正式版本还将保存播放记录和音乐索引。</p></div>';}
function about(){return compact('关于小红花')+'<div class="scroll-area"><div class="about-brand"><img src="assets/flower.svg" alt="小红花"><h2>小红花</h2><p>把喜欢的音乐，好好留在身边。</p><small>v0.1 · UI 设计原型</small></div><div class="about-copy"><p>一个安静、简单的本地音乐播放器。没有推荐流，打开就能听自己收藏的音乐。</p><p>此版本用来确认界面与操作方式。歌曲、封面和歌词为原创演示内容，播放进度为模拟。</p></div><div class="settings-card">'+settingRow('folder','本地音乐，自由聆听','手机离线播放 · 无需账号','library')+'</div></div>';}
function render(){applyTheme();applyBackground();$('#app').innerHTML=['library','albums','artists'].includes(screen)?library():screen==='playlists'?playlists():['playlist','album','artist'].includes(screen)?detail():['player','lyrics','queue'].includes(screen)?player():screen==='settings'?settings():screen==='lyric-settings'?lyricSettings():screen==='background'?backgroundPage():screen==='theme'?themePage():screen==='import'?importPage():screen==='empty'?importPage(true):screen==='search'?searchPage():screen==='info'?infoPage():screen==='folders'?folders():screen==='backup'?backup():about();$('#studio-nav').innerHTML=routes.map(([r,l])=>'<button data-page="'+r+'" class="'+(screen===r?'active':'')+'">'+l+'</button>').join('');document.title='小红花 · '+(routes.find(r=>r[0]===screen)?.[1]||'本地音乐');requestAnimationFrame(()=>{if(screen==='lyrics')layoutLyrics();updateLyrics(true);});}
function go(page){const from=screen;closeOverlay();screen=page;lyricBrowsing=false;clearTimeout(lyricResumeTimer);stopLyricAnimation();render();if(page==='queue')queueSheet();if(['player','lyrics'].includes(from)&&['player','lyrics'].includes(page)&&from!==page&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const panel=$('.player-main')||$('.lyrics-area');panel?.animate([{transform:'translateX('+(page==='lyrics'?35:-35)+'px)',opacity:.55},{transform:'translateX(0)',opacity:1}],{duration:280,easing:'cubic-bezier(.2,.7,.2,1)'});}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function closeOverlay(){const root=$('#overlay-root');root.innerHTML='';$('#app').inert=false;$('.gesture-zone').inert=false;if(lastFocus?.isConnected)lastFocus.focus();lastFocus=null;}
function overlay(title,body,dialog=false,footer=''){lastFocus=document.activeElement;$('#app').inert=true;$('.gesture-zone').inert=true;$('#overlay-root').innerHTML='<div class="overlay '+(dialog?'dialog-overlay':'')+'" data-action="dismiss"><section class="'+(dialog?'dialog':'sheet')+'" role="dialog" aria-modal="true" aria-label="'+esc(title)+'">'+(dialog?'':'<div class="sheet-handle"></div>')+'<div class="sheet-header"><h2>'+esc(title)+'</h2>'+btn('close','close','关闭')+'</div><div class="sheet-body">'+body+'</div>'+footer+'</section></div>';$('#overlay-root button, #overlay-root input')?.focus();}
function queueSheet(){overlay('播放队列 · '+queue.length+' 首','<div class="queue-controls"><button class="text-btn" data-action="mode">'+icon(mode===3?'shuffle':'repeat')+modes[mode]+'</button><span class="muted">拖动或点箭头调整</span></div>'+queue.map((id,i)=>{const s=getSong(id);return '<div class="queue-row '+(id===current?'is-current':'')+'" draggable="true" data-index="'+i+'"><span class="drag-handle" aria-hidden="true">'+icon('grip')+'</span><img src="'+art(s.cover)+'" alt=""><button class="song-hit" data-action="queue-song" data-id="'+id+'"><span class="song-copy"><strong>'+esc(s.title)+'</strong><span class="song-sub">'+s.artist+'</span></span></button><button class="icon-btn" data-action="queue-up" data-index="'+i+'" aria-label="上移'+s.title+'" '+(i===0?'disabled':'')+'>'+icon('up')+'</button><button class="icon-btn" data-action="queue-down" data-index="'+i+'" aria-label="下移'+s.title+'" '+(i===queue.length-1?'disabled':'')+'>'+icon('down')+'</button><button class="icon-btn" data-action="queue-remove" data-index="'+i+'" aria-label="移除'+s.title+'">'+icon('close')+'</button></div>';}).join('')+(queue.length?'':'<div class="empty-state"><p>队列已清空，在音乐库选择歌曲开始播放。</p></div>'));}
function playlistMenu(){const p=state.playlists.find(p=>p.id===detailId);overlay('歌单操作','<button class="sheet-action" data-action="rename-playlist">'+icon('font')+'重命名歌单</button><button class="sheet-action" data-action="playlist-order">'+icon('list')+'自定义歌曲顺序</button><button class="sheet-action" data-action="edit-playlist">'+icon('close')+'移除歌曲</button><button class="sheet-action danger" data-action="delete-playlist">'+icon('close')+'删除“'+esc(p.name)+'”</button>');}
function playlistForm(rename=false,songId=null){const p=state.playlists.find(p=>p.id===detailId);overlay(rename?'重命名歌单':songId?'新建歌单并添加':'新建歌单','<form id="playlist-form" data-rename="'+rename+'" data-song="'+(songId||'')+'"><label for="playlist-name">歌单名称</label><input id="playlist-name" maxlength="30" required placeholder="例如：散步的时候" value="'+(rename?esc(p.name):'')+'"><div class="dialog-actions"><button type="button" class="secondary" data-action="close">取消</button><button class="primary" type="submit">'+(songId?'创建并添加':'保存')+'</button></div></form>',true);$('#playlist-name').focus();}
function addSongs(){const p=state.playlists.find(p=>p.id===detailId);overlay('添加到“'+p.name+'”','<form id="add-form">'+songs.filter(s=>!p.ids.includes(s.id)).map(s=>'<label class="select-song"><img class="cover cover-small" src="'+art(s.cover)+'" alt=""><span class="song-copy"><strong>'+s.title+'</strong><small>'+s.artist+'</small></span><input type="checkbox" name="song" value="'+s.id+'" aria-label="选择'+s.title+'"></label>').join('')+'<div class="sheet-submit"><button type="submit" class="primary">添加所选歌曲</button></div></form>');}
function editPlaylist(){const p=state.playlists.find(p=>p.id===detailId);overlay('移除歌单歌曲',p.ids.map((id,i)=>{const s=getSong(id);return '<div class="queue-row"><span class="song-index">'+(i+1)+'</span><span class="song-copy"><strong>'+esc(s.title)+'</strong><small>'+esc(s.artist)+'</small></span><button class="icon-btn" data-action="playlist-remove" data-index="'+i+'" aria-label="从歌单移除'+esc(s.title)+'">'+icon('close')+'</button></div>';}).join('')+'<p class="footnote">移除只影响歌单，不删除音乐文件。</p>');}
function songMenu(id=current){const s=getSong(id);overlay(s.title,'<button class="sheet-action" data-action="favorite" data-id="'+s.id+'">'+icon('heart')+'添加到歌单</button><button class="sheet-action" data-action="enqueue" data-id="'+s.id+'">'+icon('list')+'加入播放队列</button><button class="sheet-action" data-action="info-song" data-id="'+s.id+'">'+icon('info')+'歌曲信息与歌词文件</button>');}
function favorite(id=current){addSongId=id;selectedPlaylistId=null;overlay('选择歌单','<p class="playlist-picker-song">将“'+esc(getSong(id).title)+'”添加到</p><div class="playlist-destinations" role="group" aria-label="选择目标歌单">'+state.playlists.map(p=>'<button class="playlist-destination" data-action="favorite-select" data-playlist="'+p.id+'" aria-pressed="false" '+(p.ids.includes(id)?'disabled':'')+'>'+mosaic(p)+'<span class="song-copy"><strong>'+esc(p.name)+'</strong><small>'+p.ids.length+' 首歌曲'+(p.ids.includes(id)?' · 已在歌单中':'')+'</small></span><span class="radio"></span></button>').join('')+'</div><button class="sheet-action" data-action="create-playlist" data-song="'+id+'">'+icon('plus')+'新建歌单</button><div class="sheet-submit"><button class="primary" data-action="favorite-save" disabled>添加到所选歌单</button></div>');}
function nextSong(direction){if(!queue.length){toast('队列为空，请先选择歌曲');return;}let i=queue.indexOf(current);if(mode===3&&queue.length>1){const others=queue.filter(id=>id!==current);current=others[Math.floor(Math.random()*others.length)];}else current=queue[(i+direction+queue.length)%queue.length];position=0;render();if(screen==='lyrics')scrollLyrics();}
function shuffleOrder(list,i,delta){const j=i+delta;if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];}
document.addEventListener('click',e=>{
 if(performance.now()<suppressClickUntil&&e.target.closest('.player-area')){e.preventDefault();return;}
 const target=e.target.closest('[data-page],[data-action]');if(!target)return;
 if(target.dataset.page){go(target.dataset.page);return;}const a=target.dataset.action,id=Number(target.dataset.id)||current,i=Number(target.dataset.index);
 if(a==='dismiss'){if(e.target===target)closeOverlay();return;}
 if(a==='close'){closeOverlay();return;}
 if(a==='lyric-settings'||a==='background'){settingsReturn=['player','lyrics'].includes(screen)?screen:'settings';go(a);return;}
 if(['library','search','theme','import','folders','backup','about'].includes(a)){go(a);return;}
 if(a==='back'){go(['background','lyric-settings'].includes(screen)?settingsReturn:['player','lyrics','queue','info','import','empty','search','album','artist'].includes(screen)?'library':screen==='playlist'?'playlists':'settings');return;}
 if(a==='song'||a==='queue-song'){current=id;position=0;playing=true;if(!queue.includes(id))queue.push(id);go('player');return;}
 if(a==='play'){if(!queue.includes(current))queue.push(current);playing=!playing;document.querySelectorAll('[data-action="play"]').forEach(el=>{el.innerHTML=icon(playing?'pause':'play');el.setAttribute('aria-label',playing?'暂停':'播放');el.title=playing?'暂停':'播放';});return;}
 if(a==='next'||a==='prev'){nextSong(a==='next'?1:-1);return;}
 if(a==='mode'){mode=(mode+1)%4;const open=Boolean($('#overlay-root').innerHTML);const control=$('#app .transport [data-action="mode"]');if(control){control.innerHTML=icon(mode===3?'shuffle':'repeat');control.setAttribute('aria-label',modes[mode]);control.title=modes[mode];}const label=$('#app .mode-label');if(label)label.textContent=modes[mode];if(open)queueSheet();toast(modes[mode]);return;}
 if(a==='queue'){queueSheet();return;}
 if(a==='queue-up'||a==='queue-down'){shuffleOrder(queue,i,a==='queue-up'?-1:1);queueSheet();return;}
 if(a==='queue-remove'){queue.splice(i,1);queueSheet();return;}
 if(a==='sort'){sortMenu(target.dataset.target==='library'?null:Number(target.dataset.target));return;}
 if(a==='sort-choice'){const key=target.dataset.name;if(key==='custom'){customSort();return;}const ids=sortTarget===null?songs.map(s=>s.id):state.playlists.find(p=>p.id===sortTarget).ids;if(sortTarget===null){state.librarySort=key;if(key==='random')state.libraryRandomOrder=randomized(ids);}else{const p=state.playlists.find(p=>p.id===sortTarget);p.sort=key;if(key==='random')p.randomOrder=randomized(ids);}persist();closeOverlay();render();return;}
 if(a==='order-up'||a==='order-down'){moveDraft(id,sortDraft.indexOf(id)+(a==='order-up'?-1:1));return;}
 if(a==='save-order'){if(sortTarget===null){state.libraryCustomOrder=[...sortDraft];state.librarySort='custom';}else{const p=state.playlists.find(p=>p.id===sortTarget);p.ids=[...sortDraft];p.sort='custom';}persist();closeOverlay();render();sortDraft=null;toast('歌曲顺序已保存');return;}
 if(a==='play-all'){queue=orderedIds(songs.map(s=>s.id));if(!queue.length)return;current=queue[0];playing=true;position=0;go('player');return;}
 if(a==='album'||a==='artist'){if(a==='album')album=target.dataset.name;else artist=target.dataset.name;go(a);return;}
 if(a==='playlist'){detailId=id;go('playlist');return;}
 if(a==='play-detail'){queue=screen==='playlist'?orderedIds(state.playlists.find(p=>p.id===detailId).ids,detailId):songs.filter(s=>screen==='album'?s.album===album:s.artist===artist).map(s=>s.id);if(!queue.length){toast('先给歌单添加歌曲');return;}current=queue[0];playing=true;position=0;go('player');return;}
 if(a==='create-playlist'||a==='rename-playlist'){playlistForm(a==='rename-playlist',Number(target.dataset.song)||null);return;}
 if(a==='playlist-menu'){playlistMenu();return;}
 if(a==='add-songs'){addSongs();return;}
 if(a==='edit-playlist'){editPlaylist();return;}
 if(a==='playlist-order'){customSort(detailId);return;}
 if(a==='playlist-remove'){const p=state.playlists.find(p=>p.id===detailId);p.ids.splice(i,1);persist();render();editPlaylist();return;}
 if(a==='delete-playlist'){overlay('删除歌单','<p>删除歌单不会删除音乐文件。</p><div class="dialog-actions"><button class="secondary" data-action="close">取消</button><button class="primary" data-action="confirm-delete">删除歌单</button></div>',true);return;}
 if(a==='confirm-delete'){state.playlists=state.playlists.filter(p=>p.id!==detailId);persist();go('playlists');toast('歌单已删除');return;}
 if(a==='song-menu'){songMenu(id);return;}
 if(a==='favorite'){favorite(id);return;}
 if(a==='favorite-select'){selectedPlaylistId=Number(target.dataset.playlist);$('#overlay-root').querySelectorAll('.playlist-destination').forEach(el=>{const selected=Number(el.dataset.playlist)===selectedPlaylistId;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected));});$('#overlay-root [data-action="favorite-save"]').disabled=false;return;}
 if(a==='favorite-save'){const p=state.playlists.find(p=>p.id===selectedPlaylistId);if(!p||addSongId===null)return;if(p.ids.includes(addSongId)){toast('歌曲已在这个歌单中');return;}p.ids.push(addSongId);persist();closeOverlay();render();toast('已添加到“'+p.name+'”');return;}
 if(a==='enqueue'){if(!queue.includes(id))queue.push(id);closeOverlay();toast('已加入播放队列');return;}
 if(a==='info-song'){current=id;go('info');return;}
 if(a==='font'){state.font=target.dataset.name;persist();render();return;}
 if(a==='theme-color'){state.theme=target.dataset.name;persist();render();return;}
 if(a==='theme-preview'){go('player');return;}
 if(a==='player-style'){overlay('播放样式',settingRow('font','歌词字体与字号','调整字体、字号和动态歌词','lyric-settings')+settingRow('palette','播放背景','相册图片、大小和位置','background')+settingRow('clock','定时关闭','睡前听一会儿','timer'));return;}
 if(a==='background-import'){$('#background-file').click();return;}
 if(a==='background-source'){if(target.dataset.name==='local'&&!backgroundUrl){$('#background-file').click();return;}state.background.source=target.dataset.name;persist();render();return;}
 if(a==='background-reset'){state.background=structuredClone(defaults.background);persist();render();toast('已恢复默认背景');return;}
 if(a==='background-done'){go(settingsReturn);toast('背景设置已保存');return;}
 if(a==='lyric-line'){const line=trackLyrics()[i];if(line){position=Math.min(line.at,getSong(current).duration||248);resumeLyrics();updateProgress();}return;}
 if(a==='resume-lyrics'){resumeLyrics();return;}
 if(a==='clear-search'||a==='search-chip'){search=a==='clear-search'?'':target.dataset.name;render();$('#search-input').focus();return;}
 if(a==='import-files'||a==='import-folder'){$(a==='import-files'?'#music-files':'#music-folder').click();return;}
 if(a==='rescan'){if(folderHandle)scanFolder(true);else toast('请先选择监测目录；也可查看示例变更');return;}
 if(a==='connect-folder'){connectFolder();return;}
 if(a==='demo-folder-change'){demonstrateFolderChange();return;}
 if(a==='choose-lyric'){$('#lyric-file').click();return;}
 if(a==='timer'){overlay('定时关闭','<p class="footnote">以下为交互演示，实际计时服务待安卓版本实现。</p>'+[15,30,60].map(n=>'<button class="sheet-action" data-action="timer-select" data-name="'+n+'">'+icon('clock')+n+' 分钟后</button>').join('')+'<button class="sheet-action" data-action="timer-select" data-name="取消">取消定时</button>');return;}
 if(a==='timer-select'){closeOverlay();toast(target.dataset.name==='取消'?'已取消演示定时':'已选择 '+target.dataset.name+' 分钟（演示）');return;}
 if(a==='export'){const data=JSON.stringify({kind:'xiaohonghua-ui',version:1,data:state},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='小红花-UI备份.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出歌单与界面设置');return;}
 if(a==='restore'){$('#backup-file').click();}
});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='playlist-form'){const name=$('#playlist-name').value.trim(),songId=Number(e.target.dataset.song)||null;if(!name)return;if(e.target.dataset.rename==='true')state.playlists.find(p=>p.id===detailId).name=name;else{detailId=Date.now();state.playlists.push({id:detailId,name,ids:songId?[songId]:[]});}persist();go('playlist');toast(songId?'歌单已创建，歌曲已添加':'歌单已保存');}if(e.target.id==='add-form'){const selected=[...e.target.querySelectorAll('input:checked')].map(el=>Number(el.value));if(!selected.length){toast('请先选择歌曲');return;}state.playlists.find(p=>p.id===detailId).ids.push(...selected);persist();closeOverlay();render();toast('已添加 '+selected.length+' 首歌曲');}});
document.addEventListener('input',e=>{if(e.target.id==='seek'){position=Number(e.target.value);updateProgress();resumeLyrics();}if(e.target.id==='font-size'){state.size=Number(e.target.value);applyTheme();$('#font-size-label').textContent=state.size+' px';persist();}if(e.target.id==='search-input'){search=e.target.value;$('#search-results').innerHTML=searchResults(songs.filter(s=>(s.title+s.artist+s.album).toLowerCase().includes(search.toLowerCase())));}});
document.addEventListener('input',e=>{const key=e.target.dataset.background;if(!key)return;state.background[key]=Number(e.target.value);$('#background-'+key+'-value').textContent=e.target.value+'%';applyBackground();persist();});
document.addEventListener('input',e=>{if(e.target.id==='line-gap'){state.lineGap=Number(e.target.value);$('#line-gap-label').textContent=state.lineGap+' px';applyTheme();persist();}});
document.addEventListener('wheel',e=>{if(e.target.closest('.lyrics-area'))browseLyrics();},{passive:true});
document.addEventListener('scroll',e=>{if(e.target.classList?.contains('lyrics-area')&&lyricBrowsing)browseLyrics();},true);
document.addEventListener('keydown',e=>{if(e.target.closest('.lyrics-area')&&['ArrowUp','ArrowDown','PageUp','PageDown','Home','End',' '].includes(e.key))browseLyrics();});
document.addEventListener('pointerdown',e=>{
 const handle=e.target.closest('[data-reorder]');if(handle){e.preventDefault();reorderDrag={id:Number(handle.dataset.reorder),pointer:e.pointerId,y:e.clientY,handle};handle.setPointerCapture(e.pointerId);handle.closest('.order-row').classList.add('dragging');return;}
 if($('#overlay-root').innerHTML||!['player','lyrics'].includes(screen)||!e.target.closest('.player-main,.lyrics-area')||e.target.closest('input'))return;
 if(screen==='lyrics')browseLyrics();swipe={x:e.clientX,y:e.clientY,started:performance.now(),dx:0,dy:0,horizontal:false,panel:$('.player-main')||$('.lyrics-area')};
});
document.addEventListener('pointermove',e=>{
 if(reorderDrag&&e.pointerId===reorderDrag.pointer){e.preventDefault();reorderDrag.y=e.clientY;const row=document.elementsFromPoint(e.clientX,e.clientY).map(el=>el.closest('[data-sort-id]')).find(Boolean);if(row&&Number(row.dataset.sortId)!==reorderDrag.id)moveDraft(reorderDrag.id,sortDraft.indexOf(Number(row.dataset.sortId)));const body=$('#overlay-root .sheet-body'),bounds=body.getBoundingClientRect();if(e.clientY<bounds.top+35)body.scrollTop-=12;else if(e.clientY>bounds.bottom-35)body.scrollTop+=12;return;}
 if(!swipe)return;swipe.dx=e.clientX-swipe.x;swipe.dy=e.clientY-swipe.y;
 if(Math.abs(swipe.dx)>14&&Math.abs(swipe.dx)>Math.abs(swipe.dy)*1.5)swipe.horizontal=true;
 if(swipe.horizontal){e.preventDefault();swipe.panel.style.transform='translateX('+Math.max(-65,Math.min(65,swipe.dx*.3))+'px)';}
},{passive:false});
function endPointer(e){
 if(reorderDrag&&e.pointerId===reorderDrag.pointer){reorderDrag.handle.closest('.order-row')?.classList.remove('dragging');reorderDrag=null;return;}
 if(!swipe)return;const gesture=swipe;swipe=null;gesture.panel.style.transform='';if(gesture.horizontal){suppressClickUntil=performance.now()+350;if(e.type!=='pointercancel'&&Math.abs(gesture.dx)>55){if(screen==='player'&&gesture.dx<0)go('lyrics');else if(screen==='lyrics'&&gesture.dx>0)go('player');}}else if(screen==='lyrics')browseLyrics();
}
document.addEventListener('pointerup',endPointer);document.addEventListener('pointercancel',endPointer);
window.addEventListener('resize',()=>{if(screen==='lyrics'){layoutLyrics();if(!lyricBrowsing)scrollLyrics();}});
document.addEventListener('keydown',e=>{if(!$('#overlay-root').innerHTML)return;if(e.key==='Escape'){closeOverlay();return;}if(e.key==='Tab'){const items=[...$('#overlay-root').querySelectorAll('button:not([disabled]),input,a[href]')];if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
document.addEventListener('change',e=>{const key=e.target.dataset.setting;if(key){state[key]=e.target.checked;persist();if(key==='lock')toast('已保存期望设置，系统效果待安卓实机验证');if(key==='monitor'&&screen==='folders'){render();if(state.monitor&&folderHandle)scanFolder(true);}if(key==='dynamic')toast(state.dynamic?'已启用歌词平滑滚动':'已减少歌词动画');}if(e.target.id==='device-size'){const [w,h]=e.target.value.split(',');document.documentElement.style.setProperty('--device-w',w+'px');document.documentElement.style.setProperty('--device-h',h+'px');}});
document.addEventListener('dragstart',e=>{const row=e.target.closest('.queue-row[draggable]');if(!row)return;dragIndex=Number(row.dataset.index);row.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragIndex));});
document.addEventListener('dragover',e=>{if(e.target.closest('.queue-row[draggable]'))e.preventDefault();});
document.addEventListener('drop',e=>{const row=e.target.closest('.queue-row[draggable]');if(!row||dragIndex===null)return;e.preventDefault();const destination=Number(row.dataset.index);const [id]=queue.splice(dragIndex,1);queue.splice(destination,0,id);dragIndex=null;queueSheet();});
document.addEventListener('dragend',()=>{dragIndex=null;document.querySelectorAll('.dragging').forEach(el=>el.classList.remove('dragging'));});
async function selectedFiles(e){const files=[...e.target.files].filter(f=>/\.(flac|mp3|wav|m4a|aac|ogg|opus)$/i.test(f.name));let count=0;try{for(const f of files){const filename=f.webkitRelativePath||f.name;if(songs.some(s=>s.filename===filename))continue;songs.push({...await readMusicFile(f,filename),id:Math.max(...songs.map(s=>s.id))+1});count++;}go('library');overlay('文件选择完成','<div class="import-result">'+icon('check')+'<h2>'+count+' 个新文件</h2><p>FLAC 可读取基本标签，其他格式暂按文件名展示。音频播放未实现，刷新页面后需重新选择文件或目录。</p><button class="primary" data-action="close">查看音乐库</button></div>');}catch{toast('部分文件无法读取，请重新选择');}finally{e.target.value='';}}
$('#music-files').addEventListener('change',selectedFiles);$('#music-folder').addEventListener('change',selectedFiles);
$('#lyric-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>512*1024)throw Error();const text=await file.text();if(!parseLrc(text).length)throw Error();state.lyricsBySong[current]={text,name:file.name,manual:true};persist();lyricKey='';go('lyrics');toast('已载入 '+file.name);}catch{toast('无法读取：请选择有效的 LRC 时间戳歌词');}finally{e.target.value='';}});
$('#background-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;let url='';try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20*1024*1024)throw Error('请选择 20 MB 以内的 JPG、PNG 或 WebP 图片');url=URL.createObjectURL(file);const img=new Image();img.src=url;await img.decode();if(backgroundUrl)URL.revokeObjectURL(backgroundUrl);backgroundUrl=url;url='';backgroundName=file.name;state.background={...structuredClone(defaults.background),source:'local'};let stored=true;try{await backgroundStore('put',file);}catch{stored=false;}persist();render();toast(stored?'图片已导入，可调整显示效果':'已临时导入，浏览器不允许保存图片');}catch(error){if(url)URL.revokeObjectURL(url);toast(error.message.includes('20 MB')?error.message:'无法读取图片，请换一张有效图片');}finally{e.target.value='';}});
backgroundStore('get').then(file=>{if(!(file instanceof Blob)||backgroundUrl)return;backgroundUrl=URL.createObjectURL(file);backgroundName=file.name||'本地背景图片';applyBackground();if(screen==='background')render();}).catch(()=>{/* Background can still be selected for this session. */});
$('#backup-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1024*1024)throw Error();const b=JSON.parse(await f.text()),d=b.data;if(b.kind!=='xiaohonghua-ui'||b.version!==1||!d||!Array.isArray(d.playlists)||d.playlists.length>100||!themes.some(t=>t.name===d.theme)||!['系统字体','宋体','楷体'].includes(d.font)||!Number.isFinite(d.size)||d.size<18||d.size>34||typeof d.lock!=='boolean'||typeof d.dynamic!=='boolean'||(d.background!==undefined&&!validBackground(d.background))||!validAddedSettings(d))throw Error();const ids=new Set();for(const p of d.playlists){if(!Number.isSafeInteger(p.id)||ids.has(p.id)||typeof p.name!=='string'||!p.name.trim()||p.name.length>30||!Array.isArray(p.ids)||p.ids.some(id=>!songs.some(s=>s.id===id))||new Set(p.ids).size!==p.ids.length)throw Error();ids.add(p.id);}state={...structuredClone(defaults),...d};persist();go('playlists');toast('已恢复原型歌单与设置');}catch{toast('无法恢复：请选择有效的小红花 UI 备份');}e.target.value='';});
function playbackFrame(now){if(playing&&lastFrame){position+=(now-lastFrame)/1000;const duration=getSong(current).duration||248;if(position>=duration){if(mode===2)position%=duration;else if(mode===0&&queue.indexOf(current)===queue.length-1){playing=false;position=duration;render();}else nextSong(1);}}lastFrame=now;if(playing&&now-lastPaint>80){lastPaint=now;updateProgress();updateLyrics();}requestAnimationFrame(playbackFrame);}requestAnimationFrame(playbackFrame);
const params=new URLSearchParams(location.search);if(params.has('embed'))document.body.classList.add('embed');screen=routes.some(r=>r[0]===params.get('screen'))?params.get('screen'):'library';render();if(screen==='queue')queueSheet();if(params.get('sheet')==='playlists')favorite(current);if(params.get('sheet')==='sort')sortMenu();if(params.get('sheet')==='custom-sort')customSort(null);
